import re

def get_wikipedia_page_text(title):
    """Get the full text of a Wikipedia page using the API"""
    url = "https://en.wikipedia.org/w/api.php"
    headers = {
        "User-Agent": "Mozilla/5.0 (counting Twitter references task)"
    }
    params = {
        "action": "query",
        "titles": title,
        "prop": "revisions",
        "rvprop": "content",
        "format": "json",
        "rvslots": "main"
    }
    response = requests.get(url, params=params, headers=headers)
    data = response.json()
    pages = data["query"]["pages"]
    for page_id, page in pages.items():
        if "revisions" in page:
            return page["revisions"][0].get("*", "")
    return ""

# Get text for August 1-31 pages
results = {}
for day in range(1, 32):
    title = f"August {day}"
    text = get_wikipedia_page_text(title)

    # Find the References section
    ref_section = re.search(r'== References ==.*', text, re.DOTALL)
    if ref_section:
        ref_text = ref_section.group(0)
        # Count twitter.com and x.com links in references
        twitter_in_refs = len(re.findall(r'twitter\.com', ref_text, re.IGNORECASE))
        x_in_refs = len(re.findall(r'\bx\.com\b', ref_text, re.IGNORECASE))
        total = twitter_in_refs + x_in_refs
    else:
        total = 0
        twitter_in_refs = 0
        x_in_refs = 0

    results[day] = {
        "twitter_in_refs": twitter_in_refs,
        "x_in_refs": x_in_refs,
        "total": total
    }
    if total > 0:
        print(f"August {day}: twitter={twitter_in_refs}, x={x_in_refs}, total={total}")

print("\n--- Summary ---")
for day in range(1, 32):
    print(f"August {day}: {results[day]['total']}")"}
